/* ======= Diagnostics: open the site with ?debug at the end of the address to see what a phone is doing (nothing changes without it) ======= */
if(/[?&]debug(=|&|$)/.test(location.search)){
  (function(){
    var pan = document.createElement("pre");
    pan.style.cssText = "position:fixed;left:4px;right:4px;bottom:4px;max-height:48vh;overflow:hidden;z-index:2147483647;background:rgba(0,0,0,.88);color:#9fe39f;font:10px/1.35 monospace;padding:6px 8px;margin:0;white-space:pre-wrap;word-break:break-all;pointer-events:none;border:1px solid #4a4";
    document.body.appendChild(pan);
    function tail(u){ u = u || ""; return u.length > 22 ? "…" + u.slice(-22) : u; }
    function tick(){
      var L = [];
      L.push("UA: " + navigator.userAgent.replace(/Mozilla\/5.0 /, "").slice(0, 110));
      L.push("schermo " + innerWidth + "x" + innerHeight + " @" + (window.devicePixelRatio || 1) + " | scroll " + Math.round(scrollY) + " | riduci movimento: " + (reduced ? "SI" : "no") + " | lingua: " + lang);
      L.push("versione: 25-ott-2026, ingresso: stella, alone che gira, scelta e uscita nell'acqua (Stagno); fumo sul telefono: base +60%, picchi -35%; ingresso del play in video | pagina: " + document.body.className + " | audio: " + (typeof actx !== "undefined" && actx ? actx.state : "—") + " | suono: " + (typeof soundOn !== "undefined" ? soundOn : "?") + " | fumo WebGL: " + (document.documentElement.classList.contains("gl-smoke") ? "attivo" : "no") + (window.__smokeInfo ? " (" + window.__smokeInfo + ")" : ""));
      var n = 0;
      Array.prototype.forEach.call(document.querySelectorAll("video[data-m]"), function(v){
        var r = v.getBoundingClientRect(), vis = r.height > 0 && r.bottom > 0 && r.top < innerHeight;
        if(!vis && !v.getAttribute("src")) return;
        if(++n > 12) return;
        L.push((vis ? "▶ " : "· ") + v.getAttribute("data-m") + " rs" + v.readyState + " ns" + v.networkState + " " + (v.paused ? "FERMO" : "gira") + " t=" + v.currentTime.toFixed(1) + " dur=" + (isFinite(v.duration) ? v.duration.toFixed(1) : "?") + " err=" + (v.error ? v.error.code : "-") + " on=" + (v.classList.contains("on") ? 1 : 0) + " " + tail(v.getAttribute("src")));
      });
      if(window.__errs && window.__errs.length) L.push("ERRORI: " + window.__errs.slice(-4).join(" | "));
      pan.textContent = L.join("\n");
    }
    tick(); setInterval(tick, 700);
  })();
}
